import React, { useEffect, useState } from 'react';
import { getAllOrders, getProducts, computeStats } from './api';

const STATUS_COLOR = {
  pending:   'yellow',
  confirmed: 'blue',
  shipped:   'blue',
  delivered: 'green',
  cancelled: 'red',
};

export default function AdminDashboard() {
  const [stats,   setStats]   = useState(null);
  const [recent,  setRecent]  = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      try {
        const [oRes, pRes] = await Promise.all([getAllOrders(), getProducts({ limit: 999 })]);
        const orders   = oRes.orders   || [];
        const products = pRes.products || [];
        setStats(computeStats(orders, products));
        setRecent(orders.slice(0, 8));
      } finally {
        setLoading(false);
      }
    }
    load();
  }, []);

  if (loading) return <PageLoad />;

  const cards = [
    { label: 'Total Revenue',  value: `$${(stats.revenue).toLocaleString('en', { minimumFractionDigits: 2 })}`, icon: <RevenueIcon />, color: '#c9a96e' },
    { label: 'Total Orders',   value: stats.orders,   icon: <OrderIcon />,   color: '#5b8df5' },
    { label: 'Products',       value: stats.products, icon: <BoxIcon />,     color: '#52c07a' },
    { label: 'Pending Orders', value: stats.pending,  icon: <ClockIcon />,   color: '#e05252' },
  ];

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <div>
          <h1 style={styles.h1}>Dashboard</h1>
          <p style={{ color: 'var(--muted)', fontSize: 13 }}>
            {new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric' })}
          </p>
        </div>
      </div>

      {/* Stat Cards */}
      <div style={styles.statsGrid}>
        {cards.map((c, i) => (
          <div key={i} className="card" style={{ ...styles.statCard, '--c': c.color }}>
            <div style={{ ...styles.statIcon, background: c.color + '18', color: c.color }}>
              {c.icon}
            </div>
            <div style={styles.statValue}>{c.value}</div>
            <div style={styles.statLabel}>{c.label}</div>
            <div style={{ ...styles.statAccent, background: c.color }} />
          </div>
        ))}
      </div>

      {/* Recent Orders */}
      <div className="card" style={{ marginTop: 24 }}>
        <div style={styles.sectionHead}>
          <h2 style={styles.h2}>Recent Orders</h2>
          <span style={{ fontSize: 12, color: 'var(--muted)' }}>{recent.length} latest</span>
        </div>
        <div className="table-wrap" style={{ marginTop: 16 }}>
          <table>
            <thead>
              <tr>
                <th>Order #</th>
                <th>Customer</th>
                <th>Email</th>
                <th>Amount</th>
                <th>Payment</th>
                <th>Status</th>
                <th>Date</th>
              </tr>
            </thead>
            <tbody>
              {recent.map(o => (
                <tr key={o.id}>
                  <td style={{ fontWeight: 600, color: 'var(--accent)' }}>#{o.id}</td>
                  <td>{o.user_name || '—'}</td>
                  <td style={{ color: 'var(--muted)' }}>{o.email || '—'}</td>
                  <td>${Number(o.total_amount).toFixed(2)}</td>
                  <td style={{ textTransform: 'uppercase', fontSize: 11, letterSpacing: '0.05em' }}>{o.payment_method}</td>
                  <td>
                    <span className={`badge badge-${STATUS_COLOR[o.status] || 'gray'}`}>
                      {o.status}
                    </span>
                  </td>
                  <td style={{ color: 'var(--muted)', fontSize: 12 }}>
                    {o.created_at ? new Date(o.created_at).toLocaleDateString() : '—'}
                  </td>
                </tr>
              ))}
              {!recent.length && (
                <tr><td colSpan={7} style={{ textAlign:'center', color:'var(--muted)', padding:'40px 0' }}>No orders yet</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

function PageLoad() {
  return (
    <div style={{ display:'flex', alignItems:'center', justifyContent:'center', height:'60vh' }}>
      <span className="spinner" style={{ width:32, height:32 }} />
    </div>
  );
}

const styles = {
  page: { padding: '28px 32px', maxWidth: 1200 },
  header: { display:'flex', alignItems:'flex-start', justifyContent:'space-between', marginBottom: 28 },
  h1: { fontFamily:"'Playfair Display', serif", fontSize: 28, fontWeight: 400, color: 'var(--text)', marginBottom: 4 },
  h2: { fontFamily:"'Playfair Display', serif", fontSize: 17, fontWeight: 400, color: 'var(--text)' },
  statsGrid: { display:'grid', gridTemplateColumns:'repeat(4, 1fr)', gap: 16 },
  statCard: {
    position:'relative', overflow:'hidden',
    display:'flex', flexDirection:'column', gap: 8, padding: '20px',
  },
  statIcon: {
    width: 42, height: 42, borderRadius: 10,
    display:'flex', alignItems:'center', justifyContent:'center',
    marginBottom: 6,
  },
  statValue: { fontSize: 26, fontWeight: 700, fontFamily:"'Playfair Display', serif", color:'var(--text)' },
  statLabel: { fontSize: 12, color:'var(--muted)', fontWeight: 500, letterSpacing:'0.03em' },
  statAccent: {
    position:'absolute', bottom: 0, left: 0, right: 0, height: 2,
    opacity: 0.4,
  },
  sectionHead: { display:'flex', alignItems:'center', justifyContent:'space-between' },
};

function RevenueIcon() {
  return <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/></svg>;
